from __future__ import annotations

from contextvars import ContextVar
from dataclasses import dataclass, field
from typing import Any, Dict, Optional, cast

from werkzeug.local import LocalProxy

DEFAULT_INTERRUPTION_MIN_WORDS = 3
# Tuned together with the backchannel HYPOTHESIS; re-tune when either changes.
DEFAULT_BACKCHANNEL_THRESHOLD = 0.7


@dataclass
class InterruptionConfig:
    enabled: bool = False
    # transcripts beyond min_words are automatically considered interruptions
    min_words: int = DEFAULT_INTERRUPTION_MIN_WORDS
    # below min_words, the backchannel threshold determines
    # whether the speech is ignored.
    backchannel_threshold: float = DEFAULT_BACKCHANNEL_THRESHOLD


# Per voice session data
# This is similar to how flask makes the "request" object available as a global variable
# It's a "global" variable that is local to an async task (i.e. websocket session)
@dataclass
class CallState:
    # Whether bot audio is buffered for playback or currently playing.
    is_bot_audio_active: bool = False
    silence_timeout: Optional[float] = None
    # True while the voice conversation loop handles a turn (set by EventComposer).
    is_rasa_processing: bool = False
    hangup_requested: bool = False
    connection_failed: bool = False

    interruption_config: InterruptionConfig = field(default_factory=InterruptionConfig)

    # Latency tracking - start times only
    rasa_processing_start_time: Optional[float] = None
    tts_start_time: Optional[float] = None

    # Calculated latencies (used by channels like browser_audio)
    rasa_processing_latency_ms: Optional[float] = None
    tts_first_byte_latency_ms: Optional[float] = None
    tts_complete_latency_ms: Optional[float] = None

    # Set when a barge-in is accepted and cleared when Rasa starts processing the
    # user's input. While set, bot output is withheld and the utterance's finals
    # (including split ones) are delivered as input rather than dropped.
    user_has_floor: bool = False

    # Generic field for channel-specific state data
    channel_data: Dict[str, Any] = field(default_factory=dict)

    # Language state - tracks the current language slot value
    current_language: Optional[str] = None

    def is_response_active(self) -> bool:
        """Return whether the current bot response is still in progress."""
        return self.is_rasa_processing or self.is_bot_audio_active

    def is_idle_for_silence(self) -> bool:
        """Return whether silence monitoring can treat the call as idle."""
        return not self.is_response_active()

    def is_interruptable(self) -> bool:
        if not self.interruption_config.enabled:
            return False

        # Is the bot response interruptible?
        if not self.channel_data.get("allow_interruptions", True):
            return False

        return True


_call_state: ContextVar[CallState] = ContextVar("call_state")
call_state: CallState = cast(CallState, LocalProxy(_call_state))
